-- 8 rows for posts
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES
  ('how-to-manage-your-restaurant-s-labor-force', 'How to Manage Your Restaurant’s Labor Force', 'Are you tired of laboring over your restaurant’s labor costs? Laws surrounding your workforce are tricky; rules vary from state to state and sometimes even across city lines, theyre reliant on federal guidelines,...', '[{"type":"p","text":"Are you tired of laboring over your restaurant’s labor costs? Laws surrounding your workforce are tricky; rules vary from state to state and sometimes even across city lines, theyre reliant on federal guidelines, change depending on your tipping structure and affect every aspect of your business despite the mercurial nature of all these factors combined. Labor costs are a significant chunk of your monthly expenses, too, so learning to navigate labor laws will help you exercise control over a big portion of cash outflow."},{"type":"p","text":"Rising labor costs are inevitable. The minimum wage is constantly increasing and labor costs naturally rise with it since you have to spend more on your employees; however you can use pay as an advantage to incentivize better people to join your team in the first place. Better-trained, higher-quality candidates will apply to jobs with higher salaries. Full-time employees typically seek jobs that offer health insurance and other benefits, and restaurants’ general failure to provide that kind of stability is part of the reason that employee turnover is so high throughout the industry. Well-paid staff are happy staff, and happy staff work harder and stick around longer."},{"type":"p","text":"Pay attention to overtime, as that’s another huge chunk of labor cost right there. Know which employees are nonexempt, part-time and how many hours each person can work. Keeping track of employee hours lets you prevent people from going into overtime and unnecessarily costing you money. Overtime increases when the minimum wage does, so reducing it cuts out a big expense."},{"type":"p","text":"Scheduling also has a huge impact on your employees’ mental health. Generally, the food service industry has a bad reputation for swiftly-changing schedules, unexpected overtime and shifts cut short. Sticking to a promised schedule adds stability to employees’ lives and makes it easier for them to establish an acceptable work-life balance that fosters better mental health. If possible, make steady schedules too so the employees can plan their personal lives ahead of time."},{"type":"p","text":"You can reduce your labor costs by properly training everyone brought on board. Cross-training your staff not only gives them a chance to round out their industry skills and become better-fitted for a future career, but this investment in them also pays off because your servers can act as runners, bussers and hostsso you dont need to hire those roles. Flexibility on their end equals better preparation for their career and fewer labor costs for you."},{"type":"p","text":"Join relevant organizations to stay informed, build a network of other restaurants that inform you about ever-changing labor laws, create opportunities to share ideas and stories, and make friends in the area. Between allies and a strong team, you can create a stronger organization."},{"type":"p","text":"You can reduce turnover rates by treating your employees with respect and demonstrating your investment in them, so they in turn want to give you their full commitment. Managing your labor force isn’t always about cutting costs but is sometimes just treating employees as equals. These simple steps will go a very long way toward reducing your expensesand improving your operations and bottom line, too."},{"type":"p","text":"#eatOS #WorkforceManagement"}]', 'https://static.wixstatic.com/media/a77ed6_2439da65ffc14fff8135be5cb036e925~mv2.jpeg', 'Workforce Management', 'eatOS Staff', '2021-03-03', 'published'),
  ('how-to-market-your-restaurant', 'How to Market Your Restaurant', 'New or old, all restaurants are looking for ways to get their name out there. Whether you’re launching your business from the ground-up or simply updating your strategy to excel in the digital age, any small business...', '[{"type":"p","text":"New or old, all restaurants are looking for ways to get their name out there. Whether you’re launching your business from the ground-up or simply updating your strategy to excel in the digital age, any small business can benefit from developing pointed. Thought-out marketing techniques that build brand awareness, strengthen customer relationships and highlight the successes of your restaurant."},{"type":"p","text":"Here at eatOS, we’ve developed this list of strategies for successfully marketing your restaurant onlineand keeping those new customers once you draw them in."},{"type":"h2","text":"Loyalty Programs"},{"type":"p","text":"One of the best ways to ensure customers continue giving you patronage is through reward and loyalty programs that show your appreciation for their continued support. Offering free purchases, discounts, etc. encourages customers to keep coming back to win that prize."},{"type":"p","text":"There are many online apps available to make it easy to implement loyalty programs. You can even use partnerships with third party delivery platforms to draw customers in, by offering discounts if they order directly from your website next time and then from there setting them up in the rewards program. Alternatively, you could go old-school and give out punch cards."},{"type":"h2","text":"High-Quality Photos"},{"type":"p","text":"It’s easy to draw in new customers by the look and smell of your restaurant as they pass by on the street, but harder to convey that same feeling over the internet. Including good, high-res pictures on the menu will encourage more people to try out the food. You can show off your bestselling dishes or promote items that don’t usually sell as well, drawing attention to that part of the page so customers give it a second look. Also, consider adding photos to your website immediately entice people when they navigate to your page. It doesn’t have to stop at food, either: Show off different aspects of the business to create a well-rounded idea of your establishment before setting foot in the door. Which leads us to…"},{"type":"h2","text":"Social Media"},{"type":"p","text":"Having a strong social media presence is paramount toward building a strong brand. It’s 2020, and everything is online nowif not, then that’s where most advertising takes place. People, especially younger generations, spend so much time on the internet that you’re missing out on a considerable portion of your potential customer base by neglecting that crucial sphere."},{"type":"p","text":"Don’t limit yourself to depicting food. On Instagram, for example, you can post your most delectable dishes and include photos of the storefront, customers enjoying your cuisine, and even your staff’s hard work. Its beneficial to include staff in social media posts because it strengthens your reputation as a trustworthy, worthwhile place to spend money. When people see happy employees, they trust you more."},{"type":"p","text":"You can even publish some of your recipes so that long-time customers can enjoy their favorite dishes at home. Overall, get creative with establishing pages that show off what makes your business unique. Social media is the perfect place to strengthen your brand identity and demonstrate what makes your business great."},{"type":"h2","text":"Reviews"},{"type":"p","text":"Whether you set up your page on review sites or not, people will comment on your business. Thats why its beneficial to stay ahead of the press by establishing yourself on websites like Yelp or Tripadvisor, where you can monitor the activity regularly."},{"type":"p","text":"It’s best to meet feedback head-on, since theres no way to avoid it altogether. Even bad reviews aren’t necessarily bad for business as long as they’re handled correctly, so there’s no reason to fear them. Reviews have tremendous power in the marketplace because they’re a fast and easy way for customers to determine whether a restaurant’s food and atmosphere will suit their needs, especially when they’re visiting someplace new. That’s why it’s so important to make sure that all of your information is publicly available there and up to date: Store hours, address, menu, price range and any amenities you can boast will all round out your profile and increase your chances of coaxing in a satisfied customer."},{"type":"p","text":"Don’t underestimate the power of the internet. Get on popular websites, like Google+, to increase your chances of showing up in relevant searches. For example, Google+ will put you on the map in your area to appear more prominently in searches with applicable keywords, like “NY seafood restaurants” or “Chinese food Los Angeles.” This leads us to"},{"type":"h2","text":"Geo-Targeted Ads"},{"type":"p","text":"When looking for someplace new to dine out, people tend to search within a specified location to narrow down the most suitable choices. Thus investing in geo-targeted ads will narrow down where you appear on searches, so you primarily show up near your targeted demographics within a specific city or radius. Ultimately this saves you money by limiting your clicks to people who have a higher chance of actually becoming a customer."},{"type":"p","text":"There are plenty of online ad platforms that geo-tag for free as part of their regular services like Facebook, Twitter and other ad services. Even if it costs a little money, it’s worthwhile to invest in online ad platforms that offer geo-tagging."},{"type":"h2","text":"Newsletters"},{"type":"p","text":"Direct marketing is the best way to keep up with your customers, but you need to strike a careful balance so you dont overload them. Email marketing is the most effective method for building customer relationships in this manner, but be careful: Sending letters out more than once or maybe twice a month will result in many un-subscribers. People are inundated with email marketing campaigns day in and day out, so yours has to be really impactful, informative, and infrequent enough that it’s worthwhile for them to stay."},{"type":"p","text":"If you can strike the right balance, though, email newsletters will become invaluable. Direct marketing makes it easy to reach out about new dishes, discounts and promotions that cater to their specific interests. Find free email campaign templates, or tools to create your own, online."},{"type":"p","text":"Direct marketing develops your brand identity and forms deeper bonds with your customers, so they genuinely want to interact with you more. Alternatively, or supplementary to your newsletter, you can start a company blog to talk more in-depth about your restaurant, including behind-the-scenes sneak peeks of your operations, recipes you’d like to share, or anything else that will help develop a strong brand identity. A blog will help further cultivate your community and engagement statistics."},{"type":"h2","text":"User-Generated Content"},{"type":"p","text":"User-generated content, or UGC, is a phenomenal marketing tool for any restaurant looking to grow their following and connect with their customers more intimately. Essentially, UGC encapsulates any content thats made by an unpaid third party. Any time a customer posts a picture of their dinner and tags you, that’s UGC. You can encourage this engagement by hosting contests on your social media, wherein people submit photos, tag you, and then select a winner via lottery or some other method. You can offer up a free appetizer, discount code or whatever you decide to use as an incentive."},{"type":"p","text":"Reposting or thanking those accounts who participate will show your appreciation for those customers, strengthening your bond while simultaneously garnering more customers from them. Typically people trust recommendations more when a friend or acquaintance has made them, so UGC is essentially advertising to their entire newsfeed for free. Supporting user-generated content is good for business."},{"type":"h2","text":"Advertise Good Press"},{"type":"p","text":"When someone says something good about your business, they’ve done most of the work already: All you have to do is distribute that recommendation to an even wider audience, thus doubling the initial viewership that they would get alone. This is why it’s crucial to have Google alerts for your business’s name, so you can quickly see content published in your favor. Consider setting up an “In the Press” or similar page on your website makes it easy for visitors to see that positive press easily."},{"type":"p","text":"These are just a few ways to market your restaurant, though you should use it as a jumping-off point and build on it all the time. There are more intensive, more expensive avenues you can take too: For example, third party delivery apps will take a marketing fee and automatically spread your name to their hefty, built-in customer base."},{"type":"p","text":"Using our techniques and ideas, though, you’ll have a good idea of how to begin marketing your restaurant online and building a community of dedicated customers who will value you just as much as you value them. Good marketing is the cornerstone of great success."},{"type":"p","text":"#eatOS #RestaurantMarketing"}]', 'https://static.wixstatic.com/media/a77ed6_23e6da178de649368ed8424c6d1934fc~mv2.jpeg', 'Marketing & Loyalty', 'eatOS Staff', '2021-02-26', 'published'),
  ('how-to-minimize-restaurant-labor-costs', 'How to Minimize Restaurant Labor Costs', 'Labor costs are one of the highest expenses for restaurants, in part because it’s one of the more difficult variables to control. Labor is necessary; you can’t get through a dinner rush without good cooks and...', '[{"type":"p","text":"Labor costs are one of the highest expenses for restaurants, in part because it’s one of the more difficult variables to control. Labor is necessary; you can’t get through a dinner rush without good cooks and well-trained servers."},{"type":"p","text":"As restaurants struggle with overstaffing problems, high turnover, rising minimum wage, and labor laws in flux, they’re increasingly relying on these five ways to reduce labor costs."},{"type":"h2","text":"1\\. Streamline staff schedules"},{"type":"p","text":"Over- and understaffing are real problems for restaurant owners on a day-to-day basis. As sales fluctuate depending on the season, day of the week, mealtime, nearby events, upcoming holidays, and many other factors, management needs to assess all of these variables when making the schedule."},{"type":"p","text":"Smart technology is here to help. Advanced Point of Sale systems track data so you can see how busy you’ll be based on sales history; that informs how many employees you’ll need a different work station on any given night. Integrate scheduling software like 7Shifts, which significantly reduces how long you spend working out shifts and lets employees swap them online without managerial approval. You don’t have to worry about last-minute call-outs and no-shows giving you a headache."},{"type":"h2","text":"2\\. Improve management"},{"type":"p","text":"Optimize your managerial team to watch that good behavior trickle down to junior roles. Managers are supposed to keep the business running how you want even when you’re not around, so equip them with the skills and knowledge to do so effectively. Convey your professional goals so they know exactly how to keep the restaurant at peak efficiency; for example, track of employee hours so they don’t go into overtime."},{"type":"h2","text":"3\\. Hire smarter"},{"type":"p","text":"Invest in staff from the get-go, so they start on the right path. Employee turnover is a massive problem for restaurants, as continually recruiting and training new workers leads to high labor costs. Improve your job posts to attract better-qualified candidates by offering competitive pay and benefits so they’re motivated to work harder. Cross-train employees to improve their overall efficiency and the likelihood that they’ll stay loyal to your brand as you equip them with relevant skills and show your investment in their long-term career."},{"type":"h2","text":"4\\. Treat your workforce well"},{"type":"p","text":"Taking on a mentorship role motivates your staff to work harder, which improves your labor cost percentage. Show how much you appreciate their sacrifices by celebrating their achievements, gifting rewards for those servers who net the most profit or taking hardworking shifts out for a company dinner. Even a direct thank-you goes a long way. Use pre-shift meetings to highlight superstar workers, clarify aspects of the business the team handles well, and showcase the month’s employees to encourage the rest of the staff to follow in their footsteps."},{"type":"p","text":"Show your employees where they fit into the grand scheme of operations so they see how their everyday actions matter and how they affect the rest of the team and the workflow throughout the chain of command. Improving their productivity bolsters the rest of operations, so streamlining all your workers will reduce labor cost significantly."},{"type":"h2","text":"5\\. Cutting-edge technology"},{"type":"p","text":"Invest more now to get more later. Spending money on advanced Point of Sale systems like the one powered by eatOS ultimately gives you access to superior reporting and analytics, workforce management features, integrated scheduling software, and more so you reduce your labor cost percentage in the long run. Short-term investments save you more later."},{"type":"p","text":"Schedule a demo with eatOS to learn how we’re ushering in the future of food service, today."},{"type":"p","text":"#eatOS #Restaurant"}]', 'https://static.wixstatic.com/media/a77ed6_cea3bc13b9764f80ae92d980bf371516~mv2.jpg', 'Workforce Management', 'eatOS Staff', '2021-02-24', 'published'),
  ('how-to-optimize-your-menu-for-travel', 'How to Optimize Your Menu for Travel', 'Since COVID-19 irrevocably changed the restaurant world, many businesses that never bothered with online ordering systems before suddenly found themselves scrambling to open up new channels for takeout and delivery....', '[{"type":"p","text":"Since COVID-19 irrevocably changed the restaurant world, many businesses that never bothered with online ordering systems before suddenly found themselves scrambling to open up new channels for takeout and delivery. Social distancing makes dining in dangerous, while third party delivery platforms often take high commission fees that are untenable for struggling businesses."},{"type":"p","text":"When adapting a menu for online ordering, you need to optimize the food for travel and figure out how to balance profitability with dishes that can survive the ride. It’s different than figuring out in-house menus because you need to make up the cost of delivery and still guarantee that food ends up fresh and delicious in the customer’s hands."},{"type":"p","text":"How can you get your menu fit for online ordering?"},{"type":"h2","text":"Tips to Remember"},{"type":"p","text":"Guaranteeing that your food stays fresh and just as good as what you serve in-house is tough but worthwhile, because it can vastly improve profits in the long run. Online ordering is the reason so many businesses made it these many months of COVID-19."},{"type":"p","text":"1. Curate your menu. Unfortunately, you can’t serve everything that you offer in-house. To stay on par with your brand and make your food as good as it should be, remove items that won’t hold up in transit and replace them with similar dishes that will better weather the distance."},{"type":"p","text":"2. Separate high-moisture items. Things like sauces should be packaged on the side, because when food comes pre-made with toppings it can get soggy and taste worse."},{"type":"p","text":"3. Punch a hole for steam. Hot food needs to let out steam so that what’s inside stays crispy, crunchy or whatever consistency it’s meant to be. Don’t bother doing this with items like soup or anything that spills, but for items like fries, this will help keep them the ideal texture and taste."},{"type":"p","text":"4. Separate hot and cold. Temperature-control is one of the most difficult but necessary aspects of delivery. If the drive takes an unexpectedly long time, or the courier makes multiple deliveries in one run, separately bagging items with vast temperature differences will keep the meal copacetic."},{"type":"p","text":"5. Use compartmented containers. Not only does this improve overall presentation, but it keeps foods separate so they don’t intermingle. Don’t risk bad reviews about soggy, subpar foods; though these containers are slightly more expensive, they add a little something extra to delivery and make customers more eager to entrust their online ordering with you again."},{"type":"p","text":"6. Include reheating instructions. Just like people often take home leftovers at the restaurant, people are also likely to store away some delivery after the fact.. It breeds loyalty if customers can enjoy a good meal for days on end. The average customer won’t know how to go in for seconds except hitting a few buttons on a microwave, so add instructions on the receipt, on a notecard included with the order, or as part of the packaging such as on the tape that seals the boxes shut."},{"type":"p","text":"7. Show don’t tell. Get people ready for their order by demonstrating what they can expect when they dine with you. Post pictures of your plated meals and what dishes might look like if eaten at home and post them to your social media so customers can easily visualize what it’s like to order from you. Getting them thinking about your food is the first step toward making a customer for life."},{"type":"p","text":"8. Determine a delivery radius. Figuring out what will keep food safe and high-quality without losing money on a long delivery route means determining the optimal radius to offer customers. You don’t want food sitting in the car or on the back of a bike for more than an hour because that risks the food’s temperature falling into an inedible danger zone."},{"type":"p","text":"9. Provide a good experience. With delivery, customers are paying the same price they would in-house without the ambience or good customer service they get with dine-inplus a delivery fee. Invest in small ways to maintain your brand on online orders and get creative with hospitality, so customers feel like they’re getting what they pay for."},{"type":"p","text":"Developing an online order system could be exactly what your restaurant needs to continue thriving. Optimizing your menu for travel takes time, but when its done right, you can turn the whole system into a good marketing tactic. Promote your curated menu as a special, delivery-only deal that customers will want to take advantage of, and potentially bring in altogether new audiences on top of satisfying your existing ones."},{"type":"p","text":"With these tips, you can now begin experimenting with online ordering systems at your restaurant. Knowing what foods can travel and what parts of the system need adjustment is key to creating a new, delivery-friendly menu that makes you and your customers much happier."}]', 'https://static.wixstatic.com/media/a77ed6_05396ddaf42e41eb8bb44964ed0d6e84~mv2.jpeg', 'Online Ordering', 'eatOS Staff', '2021-02-19', 'published'),
  ('how-to-optimize-your-restaurant-s-rooftop-seating', 'How to Optimize Your Restaurant’s Rooftop Seating', 'The ongoing COVID-19 pandemic has made nontraditional seating venues the new normal for restaurants. With indoor seating regulations in constant flux and many customers uncomfortable with too much proximity, restaurants...', '[{"type":"p","text":"The ongoing COVID-19 pandemic has made nontraditional seating venues the new normal for restaurants. With indoor seating regulations in constant flux and many customers uncomfortable with too much proximity, restaurants have had to get creative to optimize outdoor seatingespecially if they didn’t have an area cordoned off for such a thing before. When sidewalks, parking lots and alleyways just don’t work, more and more restaurants are moving upwards instead."},{"type":"p","text":"Why is rooftop seating the most coveted new trend? It’s easy to market, good for private events, and seems both exclusive and tasteful to guests. All this makes it a great method for increasing your overall revenue. Seating more guests never hurts. Before you can move to the rooftop, though, you’ll need to make sure you’re prepared for this new kind of outdoor seating."},{"type":"h2","text":"Making the Change"},{"type":"h2","text":"Prepare the Area"},{"type":"p","text":"You’ll need to have a good setup, not only to draw in the crowds but also to prepare for the challenges of outdoor dining. Weather, for example, can be a huge detriment to business, especially depending on where you live. Even the sunniest place in the country won’t always stay warm and dry; stock tables with umbrellas, coverings, and consider retractable awnings or screens to keep out the cold and wet. The more durable your furniture, the better prepared you’ll be to recover swiftly from inevitable inclement weather."},{"type":"p","text":"Be prepared for wind, too. Even in nice weather, it will be dominant so far from the ground. To avoid cushions and decor blowing away, anchor down everything you can and use cloth napkins to provide the most trouble-free customer experience possible."},{"type":"h2","text":"Optimize Floor Space"},{"type":"p","text":"Map out your floor plan so you have a good idea of what your rooftop can handle. Knowing how many tables and guests fit up there will make it easy to start accepting reservations and booking those tables. You might also want to rent out your rooftop for private events; in that case, you’ll need to know what small, mid-size and large gatherings should look like, how many people you can have there before you’re at capacity, and what the physical arrangements will look like so you can begin preparing packages for guests."},{"type":"p","text":"Have backup plans, too, for when things do go sideways because of rainstorms, cold spells or other unforeseen circumstances. You shouldn’t kick out guests mid-meal or have no alternative when a rooftop event has to stop. In an emergency, managers should contact all reservations and encourage guests to move it to a different night with a discount or promotion attached to the offer, and set up an indoor event space to use as backup if necessary."},{"type":"h2","text":"Create a Welcoming Environment"},{"type":"p","text":"A scenic overview can be a major selling point for the restaurant, but if you dont have a nice view then you need to emphasize the positives. Do you have a beautiful skyline? Does the sunset look particularly nice? Optimize seating with the best views and decorate the sight lines that need some work. Don’t be afraid to show off: Take pictures and post them to your own social media to entice guests to come see for themselves. You should also post your social media handles on the wall, on the menu and in other visible locations so guests can tag you in their photos of their dinner or the view; not only is that free marketing to everyone on their feed, but it fosters better customer relationships and increases the likelihood of them becoming a loyal, repeat guest."},{"type":"p","text":"Even with a great view, decorate the bare spots of the rooftop to maximize the aesthetic appeal. Make the space welcoming with classic games, string lights, paintings or any other decoration that matches the rest of your brand."},{"type":"h2","text":"Ensure Accessibility"},{"type":"p","text":"Your rooftop might be an exclusive draw compared to other eateries in town, but it shouldn’t be hard to access. Stairways might be fine for some, but elderly and disabled patrons could have difficulty, so consider elevator access. Regardless you should make the way there clear with signage, include instructions in reservation confirmations, and detail the path in your marketing so guests are never lost wondering where to go."},{"type":"h2","text":"Stock up"},{"type":"p","text":"Unless you have a room for a second kitchen on the roof, your staff is going to have to go back and forth from downstairs to serve the guests up there. This presents a huge opportunity for spills and other accidents which cost you time, money and potentially customer satisfaction. Make sure you’re stocked up on everything you can leave up there: napkins, bar supplies, and extra silverware will help prevent wasted time going back and forth. The bartender should have all the necessary tools for mixing as well as a full supply of drinks so they never leave their station."},{"type":"h2","text":"Get Licensed"},{"type":"p","text":"You might assume that just because it’s taking place on top of your building means that all the usual rules and regulations apply, but that’s not the case at all. Moving outside means you need proper licensing; some onsite contracts and insurance policies will let you expand up there no trouble, but others require special applications, so make sure you’re squared away. Also check your city’s zoning regulations and licensing laws in case you need to get an exemption there too. Talk with your businesss lawyers to ensure you’re completely good to go before seating anybody up on the roof."},{"type":"h2","text":"Open for Business"},{"type":"p","text":"Now that you’ve got all your paperwork in place, your floor plan and decor are set, and you’re ready to market your rooftop seating area, you can begin taking reservations and allowing guests up on the roof."},{"type":"p","text":"The rest is in your hands: Do you want to hire some extra security for up there? Will you be setting up live music or other forms of entertainment? With the necessities out of the way, you can begin to make your rooftop seating unique and show off what makes your restaurant the best place around to dine out."},{"type":"p","text":"#eatOS #RestaurantBusiness #Restaurants #SmallBusiness"}]', 'https://static.wixstatic.com/media/a77ed6_a053bb2c315c460cbcd249a4689e7f9b~mv2.jpeg', 'Restaurant Growth', 'eatOS Staff', '2021-02-17', 'published'),
  ('how-to-reduce-employee-turnover-at-your-restaurant', 'How to Reduce Employee Turnover at Your Restaurant', 'Skip to Main Content', '[{"type":"p","text":"Skip to Main Content"},{"type":"h2","text":"What’s Going On With the Labor Shortage?"},{"type":"p","text":"Restaurants are experiencing a labor shortage right now. Employee turnover skyrocketed during the pandemic, creating difficulties in finding workers who would stick around long-term. Even as restaurants reopen this summer, they don’t have the staff for full capacity There are a few reasons for that, among them low pay and concerns about COVID-19. Whatever your workforce’s reasoning, restaurants are struggling."},{"type":"p","text":"The first step to reducing employee turnover is understanding yours. Calculate employee turnover by:"},{"type":"p","text":"1. Deciding what time period you want to focus on. For example, monthly or quarterly metrics are useful for comparing your restaurant against the national average."},{"type":"p","text":"2. Add together how many employees you have at the beginning of the time period versus the end. Then divide by two. That’s the average number of workers you had throughout the period."},{"type":"p","text":"3. How many workers left you this year? Take that number and divide it by the average you just calculated. Turn it into a percentage to see your turnover rate."},{"type":"p","text":"Once you have your turnover rate, see how it compares to other restaurants. With an advanced Point of Sale system, you can break down your numbers further and further until you pinpoint what’s driving off new hires. Smart POS makes that kind of streamlining easy."},{"type":"p","text":"Photo by Ketut Subiyanto from Pexels"},{"type":"h2","text":"Why Employee Turnover Matters"},{"type":"p","text":"In 2020, restaurant turnover reached 130%. That’s a significant hike from the previous year. Although restaurants no longer have legal barriers to opening, the cost of living and the wages earned at a restaurant job rarely align. Thus the people willing to work might find they can’t handle the stress without better payoff; or else it’s difficult to find candidates who are both qualified and willing. So the question is: How can your restaurant recruit suitable applicants, and then keep them?"},{"type":"p","text":"The issue goes deeper than just the costs of recruitment (which can add up to thousands of dollars to replace just one worker). The constant cycle of new hires severely impacts morale. When the team can’t bond, they’re weaker. Turnover hurts the overall workplace culture, engagement and performance. Restaurants work better when its staff has time to develop systems together and find their rhythm as a team."},{"type":"h2","text":"How to Reduce Employee Turnover Long-Term"},{"type":"p","text":"Focus on hiring the best candidates for your particular workplace; that won’t look the same for every business. Choose somebody with the makings of a good fit, even if you have to train them on important aspects of the position that a more qualified applicant would already know. It’s worth the time to invest in current employees and mentor them into the workforce you want to see."},{"type":"p","text":"When it comes to making your staff happy, ultimately they’re the ones who know best what would incentivize them to stick with the company. Talk to them directly and find out what will help them perform their jobs more effectively and make them want to stay at this particular restaurant. Then streamline your new, more productive team with a smart Point of Sale capable of superior workforce management."},{"type":"p","text":"#eatOS #PointofSaleforRestaurants #RestaurantBusiness #Restaurant #WorkforceManagement"}]', 'https://static.wixstatic.com/media/a77ed6_3cb6183b10514833908e69f6fc2151f1~mv2.jpg', 'Workforce Management', 'eatOS Staff', '2021-02-12', 'published'),
  ('how-to-reduce-labor-costs-in-your-restaurant', 'How to Reduce Labor Costs in Your Restaurant', 'Every restaurant has them, they’re some of your most significant expenses, but they’re also one of the best predictors of success. No, it’s not a riddle: We’re talking about labor costs. They’re so important albeit one...', '[{"type":"p","text":"Every restaurant has them, they’re some of your most significant expenses, but they’re also one of the best predictors of success. No, it’s not a riddle: We’re talking about labor costs. They’re so important albeit one of the most challenging factors to control, because its the most effective KPI for determining the viability and profitability of your restaurant."},{"type":"p","text":"It’s not just about salaries, either. “Labor costs” encompass everything from wages to bonuses, payroll tax, healthcare, vacation and sick days, and overtime too. Though it seems straightforward to view these factors as the sole indication of where to cut costs, it’s actually more useful to address the labor cost percentagethat is, your labor cost as it relates to revenue (determined either as a percentage of total sales or of total operational costs). By tracking these trends, you can better understand and address cost control."},{"type":"p","text":"Labor cost is exponentially increasing because the minimum wage is always going up, which raises everybody’s salary across the board. Thus it’s more beneficial to track the percentage and how costs relate to revenue. Most restaurants aim for a labor cost percentage that averages between 20-30%, although that number changes depending on the specific industry. For example:"},{"type":"p","text":"1. QSRs: 29.4%"},{"type":"p","text":"2. Fast-casual establishments: 28.9%"},{"type":"p","text":"3. Casual: 33.2%"},{"type":"p","text":"4. Upscale casual: 30.4%"},{"type":"p","text":"5. Pizza: 31.3%"},{"type":"p","text":"Depending on what type of restaurant you are, you now have a basis for whether you’re performing well relative to the rest of the industry. If not, it’s time to make some adjustments."},{"type":"h2","text":"Self-Service Technology"},{"type":"p","text":"Making an initial investment in advanced technology will reap greater rewards in the long term. Self-service technology puts control into the customers’ hands, ensuring more accurate orders, eliminating lines and ultimately selling more food, both because of embedded upselling capabilities and because customers are more likely to increase their cart size when they’re not relaying it to a third party."},{"type":"p","text":"In particular, kiosks are getting more popular because you can buy them stand-alone without having to upgrade your point of sale system entirely. Learn more in-depth about how self-service kiosks are revolutionizing the food service industry."},{"type":"p","text":"All these devices combine to increase check sizes and lower your labor cost; after the initial investment, they start paying for themselves in a matter of days."},{"type":"h2","text":"Point of Sale"},{"type":"p","text":"Self-service technology works best when paired with a good point of sale system, as that’s what enables your employees to do their best work. When a PoS system is equipped with the right software, you can rely on it to automatically handle certain aspects of the job like inventory management, CRM, staff management and communication, sales reports, basic marketing, labor reports and employee scheduling."},{"type":"p","text":"The last two are especially important. Knowing how to analyze a labor report tells you what adjustments need to be made to influence the labor cost percentage effectively. Learn to analyze certain days, times and even seasons to optimize your schedule better, and see what dishes perform best and when. Even minor adjustments based on these factors add up to save on labor costs."},{"type":"h2","text":"Employee Scheduling Tools"},{"type":"p","text":"PoS systems that integrate some type of scheduling software are proven to reduce labor costs by 4%. A good employee scheduling tool automatically works for you, taking human error and time out of the equation."},{"type":"p","text":"A good program will make schedules more quickly, lower your input when sourcing shifts, reduce over- and understaffing, and track and reduce costs by analyzing the labor reports for you in this capacity. 7shifts, for example, saves clients between 1-3% on labor costs. The right scheduling tool should quickly implement beneficial changes once they’re identified, so you can start saving right away."},{"type":"h2","text":"Adjust Hours"},{"type":"p","text":"Sometimes, the answer isn’t over- or understaffing but simply that you don’t get much business on, say, Tuesday nights after 10PM. If you can identify slow nights based on your point of sale system’s progress reports, you can close early on those days, or open later if its more applicable to focus your resources on peak times instead. Automatic analysis of sales and labor reports will prioritize what works so you can lose what doesn’t."},{"type":"h2","text":"Employee Training"},{"type":"p","text":"When staff members are set up for success, they’ll form a more cohesive and efficient team. Hands-on, practical training now means they’ll spend less time struggling to learn and work simultaneously, which ultimately takes longer and provides worse results. By training better employees from the jump, you can schedule fewer workers while maintaining the same level of excellent service."},{"type":"p","text":"Employees should be well-versed in using all of your onsite technology such as the point of sale system and tableside self-services devices. They should be able to troubleshoot devices for customers even if they dont use that technology on a day-to-day basis. It’s best to have new hires shadow your most experienced or best-performing employees to learn what makes an excellent member of the team, directly from the superstar’s mouth."},{"type":"p","text":"Communicate your restaurant’s standards so workers know what the job expects of them, and additionally provide easy access to the employee handbook as a reference; this prevents them from taking time out of managements with every little question and ultimately leads to fewer costly mistakes. You should also hold refresher training courses every now and then in addition to semi-frequent performance reviews. All of this reinforces your expectations and helps your staff work toward achievable progress goals. Read more about why investing in your staff critically prepares your business for future success."},{"type":"p","text":"The restaurant industry has notoriously high turnover rates; staff retention is a major struggle for most of them to overcome. Constantly hiring and training new employees takes a massive toll on revenue, which you’ll see reflected in your labor cost percentage. If you pay staff well, give them benefits and treat them with respect, they’re more likely to stick with you long-term. You can offer additional rewards to incentivize retention, such as small prizes for the best-seller or recognizing an employee of the month. You’d be surprised how far even a simple thank-you will go toward raising staff morale."},{"type":"p","text":"It would be best if you also promoted employees who do well, or give them a raise, to demonstrate that growth is possible within the organization. Effort improves when they have a goal to work toward. Everyone wants to advance their professional career forward. This is why it’s important to never, ever raise menu prices or reduce employees’ wages to try and save money, because although it may be effective in the short-term, the long term negative impact on morale, profits and customer relations will lead to massive, irreconcilable losses over time."},{"type":"p","text":"By identifying the areas of your business that need improvement, you can optimize staff’s time to maximize efficiency. That’s what makes technology so vital to the industry; point of sale systems that can evaluate all of this for you saves time and shows you concrete changes to make. Every little bit counts; the more parts of your business that you can optimize and automate, the more these small changes will add up to reduced labor cost percentage."},{"type":"p","text":"KPIs exist to help you succeed. Learn how to analyze your labor cost percentage and affect reasonable action to improve operations, maximize the efficiency of your team, and build a more successful restaurant overall."},{"type":"p","text":"#eatOS"}]', 'https://static.wixstatic.com/media/a77ed6_f904f821a5a9469c91cd96e226e86e3a~mv2.jpeg', 'Workforce Management', 'eatOS Staff', '2021-02-10', 'published'),
  ('how-to-start-an-online-store', 'How to Start an Online Store', 'During the pandemic, restaurants searched high and low for new sales channels to tide them over. With dine-in services closed or restricted, customers turned en masse toward online ordering instead. Having an online...', '[{"type":"p","text":"During the pandemic, restaurants searched high and low for new sales channels to tide them over. With dine-in services closed or restricted, customers turned en masse toward online ordering instead. Having an online store is more popular with demographics who can’t easily walk to your restaurant. The delivery radius for your restaurant expands your potential audience beyond walk-ins."},{"type":"p","text":"Online stores are also more convenient for guests. They can add items to their cart day or night, and then simply press send when the restaurant opens. For the sake of you and your business, it’s time your restaurant got its own online store."},{"type":"h2","text":"What is eCommerce?"},{"type":"p","text":"eCommerce is the process of buying and selling items online. However, the initial understanding of that definition has expanded to mean online and physical interactions working together. This is in line with the changing needs of modern consumers."},{"type":"p","text":"For example, now they can pick up items in-store if it’s more convenient. Some digital alternatives have even applied to dine-in customers, so restaurants have considered going completely online. With QR codes, guests can scan and pull up a menu with their phones, right from their seats. Digital solutions like this rose because of COVID-19, especially as social distance made contact-free measures necessary. The more people grow comfortable with your online store, the less they want to give up the ease and efficiency of eCommerce."},{"type":"p","text":"Despite this, your online store isn’t competing with in-person services. They complement each other. Together, these channels provide the profit needed to get through this restaurant recovery period."},{"type":"p","text":"Photo courtesy of eatOS"},{"type":"h2","text":"Making a Successful Online Store"},{"type":"p","text":"Given its importance, why not make your online store as strong as possible? Connect it to an advanced Point of Sale system to get secure payment options, faster deposits, inventory management capabilities, and real-time syncing. This maximizes the potential of all your revenue streams."},{"type":"p","text":"Aside from a smart POS, increase the effectiveness of your online store by…"},{"type":"p","text":"1. optimizing your menu for mobile, especially given how on-the-go orders encompass so much of final sales."},{"type":"p","text":"2. paring down your target audience to those who spend the most time with you. eatOS Point of Sale comes with detailed sales reports that tell you who spends the most and when. That lets you build marketing campaigns geared toward their interests."},{"type":"p","text":"3. identifying what items, promotions and branding will make your eCommerce succeed."},{"type":"p","text":"4. building a website that aligns with your brand. Expand your brand recognition and potential audience by tightening your restaurant’s outward presentation."},{"type":"p","text":"As with all aspects of running a business, you get out what you put in. Dedicate yourself to your online store as much as you did with delivery and dine-in. That means promoting across your socials, offering discounts to draw in customers, and learning your store inside and out."},{"type":"h2","text":"The Power of Modern Tech"},{"type":"p","text":"Strong restaurants lean on state-of-the-art Point of Sale systems. Get the most out of your online store when you can see your sales data in real-time and analyze comparative reports for better business decisions. The pandemic has made people comfortable with digital platforms and contactless dining experiences. Thus your online store will remain profitable into the future, and it’s worth investing in now if you haven’t yet."},{"type":"p","text":"eatOS offers an all-in-one cloud-based eco-system exclusively for restaurants. From Point of Sale to Contactless Ordering, Pay & Order at Table, Kitchen Display System, Guest Facing Display, Online Ordering APP / Website and Workforce Management there is everything to help a restaurant succeed no matter the size. Click Here to Schedule a demo to learn more about how your restaurant can make a smooth transition into the world of restaurant technology made simple."},{"type":"p","text":"#eatOS #PointofSaleforRestaurants #OnlineOrdering #RestaurantBusiness #Restaurant"}]', 'https://static.wixstatic.com/media/a77ed6_ddb8259dd0744169ba4ca2a655f001de~mv2.jpeg', 'Online Ordering', 'eatOS Staff', '2021-02-05', 'published');
